import { Injectable } from "@nestjs/common";
import type { IdentityPostsDto } from "#/modules/community/schema/dto/identity-posts.dto.ts";
import type { PostCollectionDto } from "#/modules/community/schema/dto/post-collection.dto.ts";
import { ListPostsUseCase } from "#/modules/community/features/contributions/use-cases/list-posts.repository.ts";

/**
 * The Contributions contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class CommunityContributionsService {
  abstract listPosts(input: IdentityPostsDto): Promise<PostCollectionDto>;
}

@Injectable()
export class CommunityContributionsServiceImpl extends CommunityContributionsService {
  constructor(private readonly listPostsUseCase: ListPostsUseCase) {
    super();
  }

  listPosts(input: IdentityPostsDto): Promise<PostCollectionDto> {
    return this.listPostsUseCase.execute(input);
  }
}
